<?php use App\Core\Config; use App\Core\Security; ?>
<section class="page-heading"><div><p class="eyebrow">SEGURANÇA OPERACIONAL</p><h1>Backups da aplicação</h1><p>Cópias privadas do banco e arquivos enviados. A restauração exige procedimento controlado em ambiente seguro.</p></div></section>
<?php if (!empty($_SESSION['flash_success'])): ?><div class="flash flash-success"><?= htmlspecialchars((string) $_SESSION['flash_success']); unset($_SESSION['flash_success']); ?></div><?php endif; ?>
<?php if (!empty($_SESSION['flash_error'])): ?><div class="flash flash-error"><?= htmlspecialchars((string) $_SESSION['flash_error']); unset($_SESSION['flash_error']); ?></div><?php endif; ?>
<section class="card stack-gap"><div class="section-heading"><div><p class="eyebrow">CONFIGURAÇÃO</p><h2>Destino e agendamento</h2><p class="muted">O link identifica a pasta. Para gravar no Google Drive, o servidor também precisa de um token autorizado em seu arquivo de ambiente.</p></div></div><form method="post" action="<?= Config::url('/admin/backups/configuracao') ?>" class="form-grid"><input type="hidden" name="_csrf" value="<?= Security::csrfToken() ?>"><label>Destino<select name="provider"><option value="local" <?= ($settings['provider'] ?? 'local') === 'local' ? 'selected' : '' ?>>Armazenamento local seguro</option><option value="google_drive" <?= ($settings['provider'] ?? '') === 'google_drive' ? 'selected' : '' ?>>Google Drive</option></select></label><label class="full-width">Link da pasta no Google Drive<input type="url" name="google_drive_folder_link" value="<?= Security::escape((string) ($settings['google_drive_folder_link'] ?? '')) ?>" placeholder="https://drive.google.com/drive/folders/..." inputmode="url"><small class="muted">A pasta deve estar compartilhada com a conta autorizada pelo servidor.</small></label><label class="checkbox-row full-width"><input type="checkbox" name="schedule_enabled" value="1" <?= !empty($settings['schedule_enabled']) ? 'checked' : '' ?>> Ativar backup automático</label><label>Horário diário<input type="time" name="schedule_time" value="<?= Security::escape((string) ($settings['schedule_time'] ?? '03:00')) ?>"></label><div class="actions-row full-width"><button class="button button-primary" type="submit">Salvar configuração</button><?php if ($remoteConfigured): ?><button class="button button-secondary" type="submit" formaction="<?= Config::url('/admin/backups/testar-conexao') ?>">Testar conexão</button><?php endif; ?></div></form><p class="muted">Destino atual: <?= $remoteConfigured ? 'Google Drive' : 'armazenamento local seguro' ?>. O agendamento exige uma tarefa cron do cPanel executando <code>backup:schedule</code>.</p></section>
<section class="card"><div class="section-heading"><div><p class="eyebrow">HISTÓRICO</p><h2>Cópias recentes</h2></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Situação</th><th>Arquivo</th><th>Remoto</th><th>Ações</th></tr></thead><tbody><?php foreach ($backups as $backup): ?><tr><td><?= Security::escape((string) ($backup['completed_at'] ?: $backup['started_at'])) ?></td><td><?= Security::escape((string) $backup['type']) ?></td><td><?= Security::escape((string) $backup['status']) ?></td><td><?= number_format((int) $backup['size_bytes'], 0, ',', '.') ?> bytes</td><td><?= Security::escape((string) $backup['remote_status']) ?></td><td class="table-actions"><?php if (!empty($backup['local_path'])): ?><a class="button button-secondary button-small" href="<?= Config::url('/admin/backups/' . $backup['id'] . '/download') ?>">Baixar</a><?php endif; ?><?php if (($backup['remote_status'] ?? '') === 'failed'): ?><form method="post" action="<?= Config::url('/admin/backups/' . $backup['id'] . '/reenviar') ?>"><input type="hidden" name="_csrf" value="<?= Security::csrfToken() ?>"><button class="button button-secondary button-small">Reenviar</button></form><?php endif; ?><form method="post" action="<?= Config::url('/admin/backups/' . $backup['id'] . '/excluir') ?>" onsubmit="return confirm('Excluir este backup? Esta ação não pode ser desfeita.')"><input type="hidden" name="_csrf" value="<?= Security::csrfToken() ?>"><input type="hidden" name="confirmacao" value="EXCLUIR"><button class="button button-danger button-small">Excluir</button></form></td></tr><?php endforeach; ?><?php if (!$backups): ?><tr><td colspan="6">Nenhum backup registrado.</td></tr><?php endif; ?></tbody></table></div></section>
